}
if((!title.match(/<h5/))&&(title.match(/[\u4e00-\u9fa5]/))){
title='['+title+']'+'\n'
}else{title=''}
if(r!=''){
r='◎评论：\n'+r+'\n-完-'
}
result=title+a+result+b+r
</js>

